{"content":"import type { FastifyInstance } from "fastify";
import { EventService } from "../services/eventService.js";

const service = new EventService();

export async function eventRoutes(app: FastifyInstance) {
  // GET /api/v1/events?q=&category=&city=&page=&pageSize=
  app.get("/events", async (req) => {
    const q = (req.query as Record<string, string> | undefined) ?? {};
    return service.list({
      q: q.q,
      category: q.category,
      city: q.city,
      page: Number(q.page ?? 1),
      pageSize: Number(q.pageSize ?? 20),
    });
  });

  // GET /api/v1/events/:id
  app.get("/events/:id", async (req, reply) => {
    const { id } = req.params as { id: string };
    const event = await service.getById(id);
    if (!event) return reply.status(404).send({ error: "not_found" });
    return event;
  });

  // GET /api/v1/events/:id/price-history
  app.get("/events/:id/price-history", async (req) => {
    const { id } = req.params as { id: string };
    return service.priceHistory(id);
  });
}
