{"content":"import type { Event, Paginated, PricePoint } from "@ticket-masters/shared";
import type { ListEventsInput } from "../services/eventService.js";
import { MOCK_EVENTS, MOCK_PRICE_HISTORY } from "./mocks.js";

/**
 * Skeleton repo: returns mock data. Swap internals for Postgres queries later.
 * Keep method signatures stable so services don't change.
 */
export class EventRepo {
  async list(input: ListEventsInput): Promise<Paginated<Event>> {
    let data = [...MOCK_EVENTS];
    if (input.q) {
      const q = input.q.toLowerCase();
      data = data.filter((e) => e.title.toLowerCase().includes(q));
    }
    if (input.category) data = data.filter((e) => e.category === input.category);
    if (input.city) {
      const c = input.city.toLowerCase();
      data = data.filter((e) => e.city.toLowerCase().includes(c));
    }
    const total = data.length;
    const start = (input.page - 1) * input.pageSize;
    return { data: data.slice(start, start + input.pageSize), page: input.page, pageSize: input.pageSize, total };
  }

  async getById(id: string): Promise<Event | null> {
    return MOCK_EVENTS.find((e) => e.id === id) ?? null;
  }

  async priceHistory(eventId: string): Promise<PricePoint[]> {
    return MOCK_PRICE_HISTORY.filter((p) => p.eventId === eventId);
  }
}
