{"content":"import type { Listing } from "@ticket-masters/shared";
import { MOCK_LISTINGS } from "./mocks.js";

export class ListingRepo {
  async listForEvent(eventId: string, opts: { site?: string; sort?: string }): Promise<Listing[]> {
    let data = MOCK_LISTINGS.filter((l) => l.eventId === eventId);
    if (opts.site) data = data.filter((l) => l.site === opts.site);
    if (opts.sort === "price_asc") data = [...data].sort((a, b) => a.price - b.price);
    if (opts.sort === "price_desc") data = [...data].sort((a, b) => b.price - a.price);
    return data;
  }
}
