{"content":"import type { CrawlJob } from "./scrapers/base.js";

/**
 * Queue interface — skeleton uses in-memory FIFO.
 * Swap for BullMQ/Redis or SQS later without changing callers.
 */
export interface CrawlQueue {
  enqueue(job: CrawlJob): Promise<void>;
  dequeue(): Promise<CrawlJob | null>;
  size(): Promise<number>;
}

export class InMemoryQueue implements CrawlQueue {
  private items: CrawlJob[] = [];

  async enqueue(job: CrawlJob): Promise<void> {
    this.items.push(job);
  }

  async dequeue(): Promise<CrawlJob | null> {
    return this.items.shift() ?? null;
  }

  async size(): Promise<number> {
    return this.items.length;
  }
}
