{"content":"import { InMemoryQueue, type CrawlQueue } from "./queue.js";
import { SCRAPERS } from "./scrapers/sites.js";
import type { CrawlJob } from "./scrapers/base.js";

const concurrency = Number(process.env.CRAWL_CONCURRENCY ?? 5);

/** Skeleton worker loop: drains queue with N concurrent scrapers. No persistence yet. */
export async function runWorker(queue: CrawlQueue = new InMemoryQueue()) {
  console.log(`[crawler] worker starting (concurrency=${concurrency}, skeleton — no real crawling)`);

  // Seed one demo job per site so the skeleton visibly runs.
  const demoJobs: CrawlJob[] = (Object.keys(SCRAPERS) as (keyof typeof SCRAPERS)[]).map((site) => ({
    eventId: "evt-001",
    site,
    eventUrl: `https://example.com/${site}/evt-001`,
  }));
  for (const job of demoJobs) await queue.enqueue(job);

  const workers = Array.from({ length: concurrency }, async () => {
    for (;;) {
      const job = await queue.dequeue();
      if (!job) return;
      const scraper = SCRAPERS[job.site];
      try {
        const result = await scraper.scrape(job);
        console.log(`[${job.site}] done: ${result.listings.length} listings (skeleton)`);
        // TODO: persist listings + price_history to Postgres.
      } catch (err) {
        console.error(`[${job.site}] failed:`, (err as Error).message);
      }
    }
  });
  await Promise.all(workers);
  console.log("[crawler] queue drained (skeleton)");
}
