{"content":"import type { Event, Listing, PricePoint } from "@ticket-masters/shared";
import { MOCK_EVENTS, MOCK_LISTINGS, MOCK_PRICE_HISTORY } from "../mocks/events.js";

const BASE = import.meta.env.VITE_API_BASE_URL as string | undefined;

/** API client skeleton: tries the real API, falls back to mocks when offline. */
async function get<T>(path: string): Promise<T> {
  if (!BASE) throw new Error("no-base");
  const res = await fetch(`${BASE}${path}`);
  if (!res.ok) throw new Error(`api ${res.status}`);
  return res.json() as Promise<T>;
}

export async function fetchEvents(params: { q?: string; category?: string } = {}): Promise<Event[]> {
  try {
    const qs = new URLSearchParams({ ...(params.q ? { q: params.q } : {}), ...(params.category ? { category: params.category } : {}) });
    const page = await get<{ data: Event[] }>(`/events?${qs}`);
    return page.data;
  } catch {
    let data = [...MOCK_EVENTS];
    if (params.q) data = data.filter((e) => e.title.toLowerCase().includes(params.q!.toLowerCase()));
    if (params.category) data = data.filter((e) => e.category === params.category);
    return data;
  }
}

export async function fetchEvent(id: string): Promise<Event | undefined> {
  try {
    return await get<Event>(`/events/${id}`);
  } catch {
    return MOCK_EVENTS.find((e) => e.id === id);
  }
}

export async function fetchListings(eventId: string): Promise<Listing[]> {
  try {
    return await get<Listing[]>(`/events/${eventId}/listings`);
  } catch {
    return MOCK_LISTINGS.filter((l) => l.eventId === eventId);
  }
}

export async function fetchPriceHistory(eventId: string): Promise<PricePoint[]> {
  try {
    return await get<PricePoint[]>(`/events/${eventId}/price-history`);
  } catch {
    return MOCK_PRICE_HISTORY.filter((p) => p.eventId === eventId);
  }
}
