{"content":"import type { Listing, PricePoint } from "@ticket-masters/shared";

/** Cross-site comparison table — the core differentiator vs Ticketmaster. */
export function PriceComparisonTable({ listings }: { listings: Listing[] }) {
  if (listings.length === 0) return <p className="tm-empty">No listings yet (skeleton).</p>;
  const sorted = [...listings].sort((a, b) => (a.totalPrice ?? a.price) - (b.totalPrice ?? b.price));
  const best = sorted[0]?.id;
  return (
    <table className="tm-table">
      <thead>
        <tr>
          <th>Site</th><th>Section</th><th>Qty</th><th>Price</th><th>Fees est.</th><th>Total</th><th></th>
        </tr>
      </thead>
      <tbody>
        {sorted.map((l) => (
          <tr key={l.id} className={l.id === best ? "tm-best" : ""}>
            <td>{l.site}{l.id === best && <span className="tm-badge">Best</span>}</td>
            <td>{l.section ?? "—"}{l.row ? ` · Row ${l.row}` : ""}</td>
            <td>{l.quantity}</td>
            <td>${l.price}</td>
            <td>{l.feesEstimate != null ? `$${l.feesEstimate}` : "—"}</td>
            <td><strong>${l.totalPrice ?? l.price}</strong></td>
            <td><a href={l.url} target="_blank" rel="noreferrer" className="tm-link">Buy ↗</a></td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/** Placeholder chart: renders price points as bars with divs (no chart lib yet). */
export function PriceHistoryChart({ points }: { points: PricePoint[] }) {
  if (points.length === 0) return <p className="tm-empty">No price history yet (skeleton).</p>;
  const max = Math.max(...points.map((p) => p.minPrice));
  return (
    <div className="tm-chart">
      {points.map((p, i) => (
        <div key={i} className="tm-bar-wrap" title={`${p.site}: $${p.minPrice} on ${p.capturedAt.slice(0, 10)}`}>
          <div className="tm-bar" style={{ height: `${Math.round((p.minPrice / max) * 100)}%` }} />
          <span className="tm-bar-label">${p.minPrice}</span>
        </div>
      ))}
      <p className="tm-hint">Skeleton chart — plug in a chart library later.</p>
    </div>
  );
}
