{"content":"import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import type { Event, Listing, PricePoint } from "@ticket-masters/shared";
import { fetchEvent, fetchListings, fetchPriceHistory } from "../lib/api.js";
import { PriceComparisonTable, PriceHistoryChart } from "../components/prices.js";

export function EventDetailPage() {
  const { id = "" } = useParams();
  const [event, setEvent] = useState<Event | undefined>();
  const [listings, setListings] = useState<Listing[]>([]);
  const [history, setHistory] = useState<PricePoint[]>([]);

  useEffect(() => {
    fetchEvent(id).then(setEvent);
    fetchListings(id).then(setListings);
    fetchPriceHistory(id).then(setHistory);
  }, [id]);

  if (!event) return <p className="tm-empty">Loading event… (skeleton)</p>;
  const best = listings.length ? Math.min(...listings.map((l) => l.totalPrice ?? l.price)) : event.minPrice;

  return (
    <article className="tm-detail">
      <header>
        <p className="tm-eyebrow">{new Date(event.startsAt).toLocaleString()}</p>
        <h1>{event.title}</h1>
        <p>{event.venue} — {event.city}</p>
        <p className="tm-best-price">{best != null ? `Best available: $${best}` : "Prices coming soon"}</p>
        <button className="tm-cta" disabled title="Skeleton: no-op">Set price alert (soon)</button>
      </header>
      <section>
        <h2>Compare prices across sites</h2>
        <PriceComparisonTable listings={listings} />
      </section>
      <section>
        <h2>Price history</h2>
        <PriceHistoryChart points={history} />
      </section>
    </article>
  );
}
