{"content":"// Verifies every relative import in the skeleton resolves to an existing file.
import fs from "node:fs";
import path from "node:path";

const ROOT = process.argv[2];
const exts = [".ts", ".tsx", ".js", ".jsx"];
const failures = [];
let checked = 0;

function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.name === "node_modules" || e.name === "dist") continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p);
    else if (/\.tsx?$/.test(e.name)) checkFile(p);
  }
}

function checkFile(file) {
  const src = fs.readFileSync(file, "utf8");
  const re = /(?:import|export)[^'"]*from\s*["'](\.[^'"]+)["']|import\s*["'](\.[^'"]+)["']/g;
  let m;
  while ((m = re.exec(src))) {
    const spec = m[1] ?? m[2];
    checked++;
    let target = path.resolve(path.dirname(file), spec);
    // allow explicit .js ESM suffix mapping to .ts source
    const candidates = [target];
    if (target.endsWith(".js")) candidates.push(target.slice(0, -3) + ".ts", target.slice(0, -3) + ".tsx");
    for (const e of exts) candidates.push(target + e);
    candidates.push(path.join(target, "index.ts"));
    if (!candidates.some((c) => fs.existsSync(c))) {
      failures.push(`${path.relative(ROOT, file)} -> ${spec}`);
    }
  }
}

for (const d of ["shared/src", "api/src", "crawler/src", "frontend/src"]) {
  const full = path.join(ROOT, d);
  if (fs.existsSync(full)) walk(full);
}
console.log(`checked ${checked} relative imports`);
if (failures.length) {
  console.log("BROKEN:");
  for (const f of failures) console.log("  " + f);
  process.exit(1);
} else {
  console.log("all imports resolve");
}
","path":"/tmp/tm-check-imports.mjs"}

