{"content":"import type { PriceSnapshot, SitePrice } from "@ticket-masters/shared";

/** Latency budgets. Refresh SLA: full cross-site freshness < 10s. */
export const REFRESH_SLA_MS = 10_000;
export const SITE_TIMEOUT_MS = 8_000;
export const PRICE_TTL_MS = 60_000;
export const STALE_AFTER_MS = 90_000;

/**
 * Hot price cache: one entry per event, updated by crawler workers.
 * Prod implementation is Redis (hash per event + pub/sub for SSE fan-out).
 * This in-memory version stands in so the skeleton runs with no infra.
 */
export interface PriceStore {
  getSnapshot(eventId: string): Promise<PriceSnapshot | null>;
  putSitePrice(eventId: string, price: Omit<SitePrice, "stale">): Promise<void>;
}

export class InMemoryPriceStore implements PriceStore {
  private snapshots = new Map<string, PriceSnapshot>();

  /** Seed demo data so GET /prices works before any crawl runs. */
  seed(snapshot: PriceSnapshot): void {
    this.snapshots.set(snapshot.eventId, snapshot);
  }

  async getSnapshot(eventId: string): Promise<PriceSnapshot | null> {
    const snap = this.snapshots.get(eventId);
    if (!snap) return null;
    const now = Date.now();
    return {
      ...snap,
      assembledAt: new Date(now).toISOString(),
      prices: snap.prices.map((p) => ({
        ...p,
        stale: now - new Date(p.capturedAt).getTime() > STALE_AFTER_MS,
      })),
    };
  }

  async putSitePrice(eventId: string, price: Omit<SitePrice, "stale">): Promise<void> {
    const existing = this.snapshots.get(eventId);
    const prices = existing ? existing.prices.filter((p) => p.site !== price.site) : [];
    prices.push({ ...price, stale: false });
    this.snapshots.set(eventId, {
      eventId,
      prices,
      assembledAt: new Date().toISOString(),
    });
  }
}

export const priceStore: PriceStore = new InMemoryPriceStore();
","path":"api/src/cache/priceStore.ts"}

{"content":"import type { CrawlLane } from "@ticket-masters/shared";

export interface RefreshJob {
  eventId: string;
  lane: CrawlLane;
  enqueuedAt: string;
}

/**
 * API → crawler handoff. Prod implementation pushes to Redis Streams / BullMQ,
 * which the crawler workers consume (priority lane first).
 * In-memory outbox stands in for the skeleton.
 */
export interface RefreshQueue {
  enqueue(job: RefreshJob): Promise<void>;
  pending(): Promise<RefreshJob[]>;
}

export class InMemoryRefreshOutbox implements RefreshQueue {
  private jobs: RefreshJob[] = [];

  async enqueue(job: RefreshJob): Promise<void> {
    if (job.lane === "priority") this.jobs.unshift(job);
    else this.jobs.push(job);
  }

  async pending(): Promise<RefreshJob[]> {
    return [...this.jobs];
  }
}

export const refreshQueue: RefreshQueue = new InMemoryRefreshOutbox();
","path":"api/src/cache/refreshQueue.ts"}

{"content":"import type { PriceSnapshot, SitePrice } from "@ticket-masters/shared";
import { priceStore } from "../cache/priceStore.js";
import { MOCK_LISTINGS } from "./mocks.js";

/**
 * Skeleton repo: serves snapshots from the hot cache, seeded from mock
 * listings so the refresh path works before any crawl runs. Prod adds a
 * Postgres fallback for cold events.
 */
export class PriceRepo {
  private seeded = new Set<string>();

  async getSnapshot(eventId: string): Promise<PriceSnapshot | null> {
    this.seedOnce(eventId);
    return priceStore.getSnapshot(eventId);
  }

  private seedOnce(eventId: string): void {
    if (this.seeded.has(eventId)) return;
    this.seeded.add(eventId);
    const now = Date.now();
    const seen = new Map<string, SitePrice>();
    for (const l of MOCK_LISTINGS.filter((m) => m.eventId === eventId)) {
      const prev = seen.get(l.site);
      if (!prev || l.price < prev.minPrice) {
        seen.set(l.site, {
          site: l.site,
          minPrice: l.price,
          currency: l.currency,
          listingCount: 1,
          capturedAt: new Date(now - 25_000).toISOString(),
          stale: false,
        });
      }
    }
    if (seen.size > 0) {
      void priceStore.getSnapshot(eventId).then(async (existing) => {
        if (existing) return;
        for (const p of seen.values()) await priceStore.putSitePrice(eventId, p);
      });
    }
  }
}
","path":"api/src/repos/priceRepo.ts"}

{"content":"import type { PriceSnapshot } from "@ticket-masters/shared";
import { refreshQueue } from "../cache/refreshQueue.js";
import { PriceRepo } from "../repos/priceRepo.js";

export class PriceService {
  private repo = new PriceRepo();

  /** Fast path: pure cache read, no crawling on the user path. */
  async getPrices(eventId: string): Promise<PriceSnapshot | null> {
    return this.repo.getSnapshot(eventId);
  }

  /** Enqueue a priority re-crawl; workers publish updates via SSE. */
  async requestRefresh(eventId: string): Promise<{ status: string; lane: string }> {
    await refreshQueue.enqueue({ eventId, lane: "priority", enqueuedAt: new Date().toISOString() });
    return { status: "queued", lane: "priority" };
  }
}
","path":"api/src/services/priceService.ts"}

{"content":"import type { FastifyInstance } from "fastify";
import type { PriceUpdateEvent } from "@ticket-masters/shared";
import { PriceService } from "../services/priceService.js";

const service = new PriceService();

export async function priceRoutes(app: FastifyInstance) {
  // GET /api/v1/events/:id/prices — instant cache read (fast path).
  app.get("/events/:id/prices", async (req, reply) => {
    const { id } = req.params as { id: string };
    const snapshot = await service.getPrices(id);
    if (!snapshot) return reply.status(404).send({ error: "not_found" });
    return snapshot;
  });

  // POST /api/v1/events/:id/refresh — trigger priority re-crawl, returns now.
  app.post("/events/:id/refresh", async (req, reply) => {
    const { id } = req.params as { id: string };
    const result = await service.requestRefresh(id);
    return reply.status(202).send({ eventId: id, ...result });
  });

  // GET /api/v1/events/:id/prices/stream — SSE: snapshot now, live updates after.
  app.get("/events/:id/prices/stream", async (req, reply) => {
    const { id } = req.params as { id: string };
    reply.hijack();
    const res = reply.raw;
    res.writeHead(200, {
      "Content-Type": "text/event-stream",
      "Cache-Control": "no-cache",
      Connection: "keep-alive",
    });
    const send = (evt: PriceUpdateEvent) => res.write(`data: ${JSON.stringify(evt)}\n\n`);

    const snapshot = await service.getPrices(id);
    if (snapshot) send({ type: "snapshot", snapshot });

    // Skeleton: heartbeat only. Prod subscribes to Redis pub/sub here and
    // sends { type: "site-update" } as each site's worker result lands,
    // then { type: "complete" } when all sites settle or time out.
    const timer = setInterval(() => res.write(`: heartbeat\n\n`), 15_000);
    req.raw.on("close", () => clearInterval(timer));
  });
}
","path":"api/src/routes/prices.ts"}

