  enqueue(job: CrawlJob, lane?: CrawlLane): Promise<void>;
  /** Priority lane first: user-triggered refreshes jump the queue. */
  dequeue(): Promise<CrawlJob | null>;
  size(lane?: CrawlLane): Promise<number>;
}

export class InMemoryQueue implements CrawlQueue {
  private lanes: Record<CrawlLane, CrawlJob[]> = { priority: [], background: [] };

  async enqueue(job: CrawlJob, lane: CrawlLane = "background"): Promise<void> {
    this.lanes[lane].push(job);
  }

  async dequeue(): Promise<CrawlJob | null> {
    return this.lanes.priority.shift() ?? this.lanes.background.shift() ?? null;
  }

  async size(lane?: CrawlLane): Promise<number> {
    if (lane) return this.lanes[lane].length;
    return this.lanes.priority.length + this.lanes.background.length;
  }
}
