{"content":"import type { RetailSite } from "@ticket-masters/shared";

export type CrawlMode =
  | "full" // first run: metadata + seat map + prices (slow OK)
  | "prices-only"; // steady state: min prices only (must be fast)

export interface CrawlJob {
  eventId: string;
  site: RetailSite;
  eventUrl: string;
  mode: CrawlMode;
}

export interface MetadataResult {
  job: CrawlJob;
  venue?: string;
  city?: string;
  startsAt?: string;
  seatMapVersion?: string;
  error?: string;
}

export interface PriceResult {
  job: CrawlJob;
  minPrice?: number;
  currency?: string;
  listingCount?: number;
  error?: string;
}

/**
 * One adapter per retail site. Two entry points by design:
 * - fetchMetadata: runs once per event (first run), may be slow.
 * - fetchPrices: runs on every refresh, must complete within SITE_TIMEOUT_MS.
 * Prefer the site's JSON endpoints over headless browsers on the prices path.
 */
export abstract class BaseScraper {
  abstract readonly site: RetailSite;
  abstract fetchMetadata(job: CrawlJob): Promise<MetadataResult>;
  abstract fetchPrices(job: CrawlJob): Promise<PriceResult>;

  protected userAgent(): string {
    return process.env.CRAWL_USER_AGENT ?? "TicketMastersBot/0.1";
  }
}
