{"content":"import type { PriceSnapshot, SitePrice } from "@ticket-masters/shared";

/**
 * Crawler-side writer for the hot price cache. Prod: same Redis the API reads
 * (hash per event + publish per site-update for SSE fan-out). In-memory here
 * so the skeleton runs with no infra; API and crawler each hold one instance.
 */
export interface PriceWriter {
  putSitePrice(eventId: string, price: Omit<SitePrice, "stale">): Promise<void>;
  getSnapshot(eventId: string): Promise<PriceSnapshot | null>;
}

export class InMemoryPriceWriter implements PriceWriter {
  private snapshots = new Map<string, PriceSnapshot>();

  async putSitePrice(eventId: string, price: Omit<SitePrice, "stale">): Promise<void> {
    const existing = this.snapshots.get(eventId);
    const prices = existing ? existing.prices.filter((p) => p.site !== price.site) : [];
    prices.push({ ...price, stale: false });
    this.snapshots.set(eventId, { eventId, prices, assembledAt: new Date().toISOString() });
    // TODO (prod): publish site-update to Redis pub/sub for SSE fan-out.
  }

  async getSnapshot(eventId: string): Promise<PriceSnapshot | null> {
    return this.snapshots.get(eventId) ?? null;
  }
}
