{"content":"import type { RetailSite } from "@ticket-masters/shared";
import { InMemoryQueue, type CrawlQueue } from "./queue.js";
import { SCRAPERS } from "./scrapers/sites.js";
import type { CrawlJob } from "./scrapers/base.js";
import { InMemoryPriceWriter, type PriceWriter } from "./store.js";

/** Refresh SLA: full cross-site freshness < 10s. One slow site must not blow it. */
export const SITE_TIMEOUT_MS = Number(process.env.SITE_TIMEOUT_MS ?? 8_000);
/** Background polling cadence. Hot = near-term / watched events. */
export const HOT_POLL_MS = Number(process.env.HOT_POLL_MS ?? 30_000);
export const COLD_POLL_MS = Number(process.env.COLD_POLL_MS ?? 600_000);

const SITES = Object.keys(SCRAPERS) as RetailSite[];

function withTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
  let timer: NodeJS.Timeout;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new Error(`${label} timed out after ${ms}ms`)), ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer)) as Promise<T>;
}

function jobFor(eventId: string, site: RetailSite, mode: CrawlJob["mode"]): CrawlJob {
  return { eventId, site, mode, eventUrl: `https://example.com/${site}/${eventId}` };
}

/**
 * First run per event: full mode for every site (metadata + seat map + prices).
 * Slow is OK here; result warms Postgres (metadata) and the price cache.
 */
export async function runFirstCrawl(
  eventId: string,
  queue: CrawlQueue = new InMemoryQueue(),
  store: PriceWriter = new InMemoryPriceWriter(),
): Promise<void> {
  console.log(`[crawler] first crawl for ${eventId} (full mode, slow OK)`);
  for (const site of SITES) await queue.enqueue(jobFor(eventId, site, "full"), "background");
  await drain(queue, store, { timeoutMs: 60_000 });
  console.log(`[crawler] first crawl done for ${eventId} — event is warmed`);
}

/**
 * Steady-state refresh: prices-only, all sites in parallel, each capped by
 * SITE_TIMEOUT_MS. Partial results win: whatever settles in time is published;
 * timed-out sites keep serving last-known prices (marked stale by the API).
 */
export async function runRefresh(
  eventId: string,
  store: PriceWriter = new InMemoryPriceWriter(),
): Promise<{ settled: number; failed: string[] }> {
  const started = Date.now();
  const results = await Promise.allSettled(
    SITES.map(async (site) => {
      const job = jobFor(eventId, site, "prices-only");
      const res = await withTimeout(SCRAPERS[site].fetchPrices(job), SITE_TIMEOUT_MS, site);
      if (res.minPrice == null) throw new Error(`${site}: no price returned`);
      await store.putSitePrice(eventId, {
        site,
        minPrice: res.minPrice,
        currency: res.currency ?? "USD",
        listingCount: res.listingCount,
        capturedAt: new Date().toISOString(),
      });
      return site;
    }),
  );
  const failed = results
    .map((r, i) => ({ r, site: SITES[i]! }))
    .filter(({ r }) => r.status === "rejected")
    .map(({ site, r }) => {
      console.error(`[${site}] refresh failed:`, (r as PromiseRejectedResult).reason?.message);
      return site;
    });
  console.log(
    `[crawler] refresh ${eventId}: ${SITES.length - failed.length}/${SITES.length} sites in ${Date.now() - started}ms`,
  );
  return { settled: SITES.length - failed.length, failed };
}

/** Queue drain for first-crawl (full mode) jobs. Refresh bypasses the queue. */
async function drain(queue: CrawlQueue, store: PriceWriter, opts: { timeoutMs: number }) {
  for (;;) {
    const job = await queue.dequeue();
    if (!job) return;
    const scraper = SCRAPERS[job.site];
    try {
      const meta = await withTimeout(scraper.fetchMetadata(job), opts.timeoutMs, `${job.site}:metadata`);
      // TODO: persist metadata + seat map to Postgres.
      const prices = await withTimeout(scraper.fetchPrices(job), opts.timeoutMs, `${job.site}:prices`);
      if (prices.minPrice != null) {
        await store.putSitePrice(job.eventId, {
          site: job.site,
          minPrice: prices.minPrice,
          currency: prices.currency ?? "USD",
          listingCount: prices.listingCount,
          capturedAt: new Date().toISOString(),
        });
      }
      console.log(`[${job.site}] first crawl done (seatMap=${meta.seatMapVersion})`);
    } catch (err) {
      console.error(`[${job.site}] first crawl failed:`, (err as Error).message);
    }
  }
}

/** Skeleton demo: first-crawl one event, then run one priority refresh. */
export async function runWorker(
  queue: CrawlQueue = new InMemoryQueue(),
  store: PriceWriter = new InMemoryPriceWriter(),
) {
  console.log(`[crawler] worker starting (siteTimeout=${SITE_TIMEOUT_MS}ms, hot=${HOT_POLL_MS}ms, cold=${COLD_POLL_MS}ms)`);
  await runFirstCrawl("evt-001", queue, store);
  await runRefresh("evt-001", store);
  console.log("[crawler] demo done (skeleton — no real crawling, no Redis yet)");
}
