{"content":"import { useEffect, useState } from "react";
import type { PriceSnapshot, PriceUpdateEvent } from "@ticket-masters/shared";
import { apiBase, fetchPrices } from "../lib/api.js";

/**
 * Live price stream skeleton. Shows cached snapshot instantly (~ms), then
 * upgrades to SSE updates as each site's refresh lands. Falls back to the
 * one-shot cache read when SSE is unavailable (offline skeleton).
 */
export function usePriceStream(eventId: string) {
  const [snapshot, setSnapshot] = useState<PriceSnapshot | null>(null);
  const [live, setLive] = useState(false);

  useEffect(() => {
    let cancelled = false;
    let es: EventSource | null = null;

    fetchPrices(eventId).then((s) => {
      if (!cancelled) setSnapshot(s);
    });

    try {
      es = new EventSource(`${apiBase()}/events/${eventId}/prices/stream`);
      es.onmessage = (msg) => {
        try {
          const evt = JSON.parse(msg.data) as PriceUpdateEvent;
          if (!cancelled && (evt.type === "snapshot" || evt.type === "site-update")) {
            setSnapshot(evt.snapshot);
            setLive(true);
          }
        } catch {
          // ignore malformed SSE frames in skeleton
        }
      };
      es.onerror = () => {
        es?.close();
        if (!cancelled) setLive(false);
      };
    } catch {
      // EventSource unavailable: cached snapshot only
    }

    return () => {
      cancelled = true;
      es?.close();
    };
  }, [eventId]);

  return { snapshot, live };
}
