{"content":"import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import type { Event, PricePoint } from "@ticket-masters/shared";
import { fetchEvent, fetchPriceHistory, requestRefresh } from "../lib/api.js";
import { usePriceStream } from "../hooks/usePriceStream.js";
import { SitePriceTable, PriceHistoryChart } from "../components/prices.js";

export function EventDetailPage() {
  const { id = "" } = useParams();
  const [event, setEvent] = useState<Event | undefined>();
  const [history, setHistory] = useState<PricePoint[]>([]);
  const [refreshing, setRefreshing] = useState(false);
  const { snapshot, live } = usePriceStream(id);

  useEffect(() => {
    fetchEvent(id).then(setEvent);
    fetchPriceHistory(id).then(setHistory);
  }, [id]);

  if (!event) return <p className="tm-empty">Loading event… (skeleton)</p>;
  const best = snapshot?.prices.length
    ? Math.min(...snapshot.prices.map((p) => p.minPrice))
    : event.minPrice;

  return (
    <article className="tm-detail">
      <header>
        <p className="tm-eyebrow">{new Date(event.startsAt).toLocaleString()}</p>
        <h1>{event.title}</h1>
        <p>{event.venue} — {event.city}</p>
        <p className="tm-best-price">{best != null ? `Best available: $${best}` : "Prices coming soon"}</p>
        <div className="tm-detail-actions">
          <button
            className="tm-cta"
            disabled={refreshing}
            onClick={async () => {
              setRefreshing(true);
              await requestRefresh(id);
              // Skeleton: re-enable after the 10s SLA window; prod flips
              // back on the SSE "complete" event.
              setTimeout(() => setRefreshing(false), 10_000);
            }}
          >
            {refreshing ? "Refreshing…" : "Refresh prices"}
          </button>
          <span className={live ? "tm-live" : "tm-hint"}>
            {live ? "● live" : "cached snapshot"}
          </span>
        </div>
      </header>
      <section>
        <h2>Compare prices across sites</h2>
        <SitePriceTable snapshot={snapshot} />
      </section>
      <section>
        <h2>Price history</h2>
        <PriceHistoryChart points={history} />
      </section>
    </article>
  );
}
